from flask import Flask, request, jsonify
import uuid

app = Flask(__name__)

# Dictionary to store the shares
shares = {}

@app.route('/screenshare', methods=['POST'])
def create_share():
    url = request.get_json()['url']
    share_id = str(uuid.uuid4())
    shares[share_id] = url
    return jsonify({'url': f'https://yourwebsite.com/screenshare/{share_id}'})

@app.route('/screenshare/<share_id>', methods=['GET'])
def get_share(share_id):
    if share_id in shares:
        return jsonify({'url': shares[share_id]})
    else:
        return jsonify({'error': 'Invalid share ID'}), 404

if __name__ == '__main__':
    app.run(debug=True)
```

